def bucket_of(input_str):
    lower_input = input_str.lower()
    water_words = any(word in lower_input for word in ['water', 'wet', 'wash'])
    slime_phrase = 'slime' in lower_input or 'i don\'t know' in lower_input
    if water_words and slime_phrase:
        return 'sludge'
    elif water_words:
        return 'water'
    elif slime_phrase:
        return 'slime'
    else:
        return 'air'
